import numpy as np, collections, itertools
def analyze(I,O):
    H,W=len(I),len(I[0])
    bg=collections.Counter(x for row in I for x in row).most_common(1)[0][0]
    cells={}
    for r,row in enumerate(I):
        for c,x in enumerate(row):
            if x!=bg: cells.setdefault(x,[]).append((r,c))
    bigmax=max(cells,key=lambda k:len(cells[k]))
    sing=min(cells,key=lambda k:len(cells[k]))[0]
    blk=[p for p in cells[bigmax]]
    cr=(min(p[0] for p in blk)+max(p[0] for p in blk))/2.0
    cc=(min(p[1] for p in blk)+max(p[1] for p in blk))/2.0
    orig=set(cells[sing]); Oset=set((r,c) for r in range(H) for c in range(W) if O[r][c]==sing)
    added=Oset-orig
    funcs={'id':(lambda r:r,lambda c:c),
           'h':(lambda r:r,lambda c:int(round(2*cc-c))),
           'v':(lambda r:int(round(2*cr-r)),lambda c:c),
           'hv':(lambda r:int(round(2*cr-r)),lambda c:int(round(2*cc-c)))}
    for n,f in funcs.items():
        tp={(f(r,c)[0],f(r,c)[1]) for r,c in orig}
        cov=len(tp&added); tot=len(tp)
        print(n,'oforig',tot,'covadded',cov,'inS ok' if tp<=Oset else 'OVERFLOW')
    return orig,added,(cr,cc)
