    # block color = color whose largest component has >=4 cells; singles = other
    def comps(v):
        pts=set(v); seen=set(); out=[]
        for p in pts:
            if p in seen: continue
            st=[p]; comp=set()
            while st:
                q=st.pop()
                if q in seen: continue
                seen.add(q); comp.add(q)
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        t=(q[0]+dr,q[1]+dc)
                        if t in pts and t not in seen: st.append(t)
            out.append(comp)
        return out
    big=max(comps([p for v in cells.values() for p in v]),key=len)
    bk_=big
    # block color key: color containing the 2x2 solid block
